7	export function ThemeToggle() {
8	  const { resolvedTheme, setTheme } = useTheme();
9	  const [mounted, setMounted] = useState(false);
10	  useEffect(() => setMounted(true), []);
11	
12	  const isDark = mounted && resolvedTheme === "dark";
13	  return (
14	    <Button
15	      variant={ButtonVariant.ghost}
16	      size={ButtonSize.sm}
17	      onClick={() => setTheme(isDark ? "light" : "dark")}
18	    >
